// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt) public {
        vm.assume(depositAmt > 0 && depositAmt <= 1e30);
        address actor = address(0xABCD);
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        withdrawAmt = bound(withdrawAmt, 0, depositAmt);
        vm.prank(actor);
        c.withdraw(withdrawAmt);

        bool ok;
        vm.prank(actor);
        try c.refund() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
